//! The fluent localization scaffold (the cosmic-app-template shape over
//! libcosmic's own `localize.rs`): the catalogs under `i18n/` embedded into
//! the binary, `en` as the fallback language, and the [`fl!`](crate::fl)
//! macro (placeables and all). The catalogs are generated by
//! `scripts/extract_xcstrings.py` — Swift `%@`/`%lld`/`%d` markers arrive
//! as fluent `{$name}` placeables, port-added strings merge in from
//! `i18n/port-strings.json`, and a value's real newlines ride indented
//! continuation lines (fluent text has no `\n` escape). Selection happens
//! once at startup: the persisted `language` override
//! ([`localize_with_override`], upstream's next-launch `AppleLanguages`)
//! or the desktop request ([`localize`]).

use std::sync::{LazyLock, OnceLock};

use i18n_embed::fluent::{FluentLanguageLoader, fluent_language_loader};
use i18n_embed::{DefaultLocalizer, LanguageLoader, Localizer};
use rust_embed::RustEmbed;

#[derive(RustEmbed)]
#[folder = "i18n/"]
struct Localizations;

pub static LANGUAGE_LOADER: LazyLock<FluentLanguageLoader> = LazyLock::new(|| {
    let loader: FluentLanguageLoader = fluent_language_loader!();
    loader
        .load_fallback_language(&Localizations)
        .expect("the embedded en catalog must load");
    loader
});

static SELECTION: OnceLock<()> = OnceLock::new();

pub fn localizer() -> Box<dyn Localizer> {
    Box::from(DefaultLocalizer::new(&*LANGUAGE_LOADER, &Localizations))
}

/// Select the user's requested languages against the embedded catalogs.
/// Idempotent (the [`fl!`](crate::fl) macro calls it before every lookup,
/// so a first use outside `main` still selects exactly once).
pub fn localize() {
    SELECTION.get_or_init(|| {
        let localizer = localizer();
        let requested_languages = i18n_embed::DesktopLanguageRequester::requested_languages();
        if let Err(error) = localizer.select(&requested_languages) {
            eprintln!("cad-studio: language selection failed: {error}");
        }
    });
}

/// Select exactly `language` ("en", "it", …), overriding the desktop
/// request. The test seam that pins `fl!` output to one catalog so the
/// host locale cannot decide test outcomes.
pub fn select(language: &str) {
    let tag = language
        .parse::<i18n_embed::unic_langid::LanguageIdentifier>()
        .expect("a valid language tag");
    SELECTION.get_or_init(|| ());
    if let Err(error) = i18n_embed::select(&*LANGUAGE_LOADER, &Localizations, &[tag]) {
        eprintln!("cad-studio: language selection failed: {error}");
    }
}

/// The startup entry: the persisted language override (upstream's
/// `AppleLanguages`, a next-launch setting the settings window writes)
/// selects exactly that language; no override (or one that doesn't parse —
/// a hand-edited settings.json) falls back to the desktop request. An
/// invalid tag must not take the app down over a preference.
pub fn localize_with_override(language: Option<&str>) {
    match language.and_then(|tag| {
        tag.parse::<i18n_embed::unic_langid::LanguageIdentifier>()
            .ok()
    }) {
        Some(tag) => {
            SELECTION.get_or_init(|| ());
            if let Err(error) = i18n_embed::select(&*LANGUAGE_LOADER, &Localizations, &[tag]) {
                eprintln!("cad-studio: language selection failed: {error}");
            }
        }
        None => localize(),
    }
}

/// One arg-less lookup for [`fl!`](crate::fl), isolates stripped (see
/// [`strip_isolates`]).
pub fn lookup(message_id: &str) -> String {
    strip_isolates(LANGUAGE_LOADER.get(message_id))
}

/// One formatted lookup for [`fl!`](crate::fl), isolates stripped (see
/// [`strip_isolates`]).
pub fn lookup_args(message_id: &str, args: std::collections::HashMap<&str, String>) -> String {
    strip_isolates(LANGUAGE_LOADER.get_args(message_id, args))
}

/// `format_pattern` wraps every interpolated arg in bidi isolate code
/// points (U+2068/U+2069) per the fluent spec; i18n-embed exposes no
/// `set_use_isolating(false)` knob. They are invisible when rendered but
/// would ride into chat.json and string comparisons, so `fl!` strips them:
/// upstream's `String(format:)` interpolates plain text.
fn strip_isolates(text: String) -> String {
    text.replace(['\u{2068}', '\u{2069}'], "")
}

/// Look up `message_id` in the selected catalog (en fallback), formatting
/// the value's `{$placeables}` from named args — `fl!("versione-lld",
/// version = 3)`. Arg values go through `Display` (the loader's arg map
/// takes strings), so numbers format exactly as Rust prints them. First use
/// selects the desktop's requested languages via [`localize`].
#[macro_export]
macro_rules! fl {
    ($message_id:literal) => {{
        $crate::localize::localize();
        $crate::localize::lookup($message_id)
    }};
    ($message_id:literal, $($name:ident = $value:expr),+ $(,)?) => {{
        $crate::localize::localize();
        let mut args: std::collections::HashMap<&str, String> =
            std::collections::HashMap::new();
        $( args.insert(stringify!($name), ($value).to_string()); )+
        $crate::localize::lookup_args($message_id, args)
    }};
}

/// Pin `en` for a string-asserting test and hold the language guard for as
/// long as the returned value lives (bind it: `let _lang = pin_en();`).
/// The suite runs in parallel threads over ONE global loader; the guard is
/// what keeps a test that flips the language (the override test below)
/// from interleaving with another test's text assertions.
#[cfg(test)]
pub(crate) fn pin_en() -> std::sync::MutexGuard<'static, ()> {
    let guard = LANGUAGE_GUARD.lock().unwrap_or_else(|e| e.into_inner());
    select("en");
    guard
}

#[cfg(test)]
static LANGUAGE_GUARD: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;
    use std::path::PathBuf;

    /// One parsed `key = value` entry of a generated .ftl file: the value's
    /// continuation lines (an indented line is a real newline in the value)
    /// already folded back in.
    fn parse_ftl(path: &str) -> Vec<(String, String)> {
        let text = std::fs::read_to_string(path).unwrap();
        let mut out: Vec<(String, String)> = Vec::new();
        for line in text.lines() {
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            if let Some(rest) = line.strip_prefix(' ') {
                // a continuation line: a real newline plus the de-indented text
                let value = &mut out.last_mut().expect("continuation follows an entry").1;
                value.push('\n');
                value.push_str(rest);
            } else {
                // `key =` alone opens a block value made of continuation lines.
                let (key, value) = line
                    .split_once(" = ")
                    .or_else(|| line.strip_suffix(" =").map(|k| (k, "")))
                    .expect("`key = value` lines");
                out.push((key.to_string(), value.to_string()));
            }
        }
        out
    }

    fn i18n_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("i18n")
    }

    /// `{$name}` placeable names in a value, in order.
    fn placeables(value: &str) -> Vec<&str> {
        let mut names = Vec::new();
        let mut rest = value;
        while let Some(open) = rest.find("{$") {
            let after = &rest[open + 2..];
            let close = after
                .find('}')
                .unwrap_or_else(|| panic!("unclosed placeable in {value:?}"));
            names.push(&after[..close]);
            rest = &after[close + 1..];
        }
        names
    }

    /// The catalog audit: iterate the UNION of keys
    /// across all four catalogs and fail on any file missing a key —
    /// per-file iteration passes silently when it/de/fr lose keys. Placeholder
    /// name sets must agree too (call sites pass args by name against the en
    /// file of record), and no Swift-era marker may survive anywhere.
    #[test]
    fn all_four_catalogs_carry_the_same_keys_and_placeables() {
        let langs = ["en", "it", "de", "fr"];
        let parsed: Vec<_> = langs
            .iter()
            .map(|lang| parse_ftl(&i18n_dir().join(lang).join("main.ftl").to_string_lossy()))
            .collect();

        let union: BTreeSet<&str> = parsed
            .iter()
            .flat_map(|entries| entries.iter().map(|(key, _)| key.as_str()))
            .collect();
        assert!(
            !union.is_empty(),
            "the catalogs parsed — a header-only file means the parser broke"
        );
        for (lang, entries) in langs.iter().zip(&parsed) {
            let keys: BTreeSet<&str> = entries.iter().map(|(key, _)| key.as_str()).collect();
            let missing: Vec<_> = union.difference(&keys).collect();
            assert!(
                missing.is_empty(),
                "{lang} is missing keys the other catalogs carry: {missing:?}"
            );
            let extra: Vec<_> = keys.difference(&union).collect();
            assert!(
                extra.is_empty(),
                "{lang} parse produced junk keys: {extra:?}"
            );
        }

        let en = &parsed[0];
        assert_eq!(en.len(), union.len(), "no duplicate keys in en");
        // the marker sweep covers EVERY file's values: a stray marker in
        // it/de/fr where en has no placeable would pass an en-only check
        for (lang, entries) in langs.iter().zip(&parsed) {
            for (key, value) in entries {
                assert!(
                    !value.contains("%@")
                        && !value.contains("%lld")
                        && !value.contains("%d")
                        // %.Nf floats and any other %-prefixed conversion
                        // (a bare % followed by '.' or a digit is never
                        // legitimate fluent text here)
                        && !value
                            .match_indices('%')
                            .any(|(i, _)| value[i + 1..].starts_with('.') || value[i + 1..].starts_with(|c: char| c.is_ascii_digit())),
                    "{lang} {key} still carries a Swift marker: {value:?}"
                );
            }
        }
        for (lang, entries) in langs.iter().zip(&parsed) {
            for (key, value) in entries {
                let names: BTreeSet<_> = placeables(value).into_iter().collect();
                let en_names: BTreeSet<&str> = placeables(
                    &en.iter()
                        .find(|(en_key, _)| en_key == key)
                        .expect("union check already proved the key present")
                        .1,
                )
                .into_iter()
                .collect();
                assert_eq!(
                    names, en_names,
                    "{key}: {lang} placeables must match en (call sites pass args by name)"
                );
            }
        }
    }

    /// The five formerly format-only keys (all pure punctuation upstream,
    /// every one of which sanitized to `key`) carry real names in all four
    /// catalogs.
    #[test]
    fn the_five_format_only_keys_are_renamed_everywhere() {
        for lang in ["en", "it", "de", "fr"] {
            let entries = parse_ftl(&i18n_dir().join(lang).join("main.ftl").to_string_lossy());
            for key in [
                "motion-value-row",
                "version-timestamps",
                "activity-accessibility-label",
                "speed-option",
                "settings-none",
            ] {
                assert!(
                    entries.iter().any(|(k, _)| k == key),
                    "{lang} is missing the renamed key {key}"
                );
            }
        }
    }

    /// fl! formats named placeables from args (the placeable migration's
    /// whole point): the en values, args in call order.
    #[test]
    fn fl_formats_named_placeables() {
        let _lang = pin_en();
        assert_eq!(fl!("versione-lld", version = 3), "Version 3");
        assert_eq!(
            fl!("speed-option", speed = "0.25"),
            "0.25×",
            "preformatted strings pass through verbatim"
        );
        assert_eq!(
            fl!("motion-value-row", name = "angle", value = 45),
            "angle 45",
            "numbers format through Display"
        );
        assert_eq!(
            fl!(
                "l-animazione-ha-collisioni-tra-parti-in-lld-fotogrammi",
                frames = 2
            ),
            "The animation has collisions between parts in 2 frames"
        );
    }

    /// A value's real newlines survive the round trip (the ask-agent-to-fix
    /// prompt is a three-line code fence): fluent renders the continuation
    /// line's break as a newline, never the two-character `\n` the old
    /// extractor wrote.
    #[test]
    fn multiline_values_keep_real_newlines() {
        let _lang = pin_en();
        let text = fl!(
            "l-esecuzione-di-model-py-non-riesce-con-questo-errore-correggi-lo-script",
            error = "SyntaxError"
        );
        assert!(
            text.contains('\n'),
            "the code fence must break lines: {text:?}"
        );
        assert!(!text.contains("\\n"), "no literal backslash-n: {text:?}");
        assert!(
            text.contains("```"),
            "the fence markers ride along: {text:?}"
        );
        assert_eq!(fl!("about-credit").matches('\n').count(), 1);
    }

    /// The port-added strings (no upstream key) are in every catalog, so a
    /// non-en selection never falls back mid-sentence on them.
    #[test]
    fn port_added_keys_exist_in_every_catalog() {
        for lang in ["en", "it", "de", "fr"] {
            let entries = parse_ftl(&i18n_dir().join(lang).join("main.ftl").to_string_lossy());
            for key in [
                "python-setup-required",
                "ha-terminato-con-un-errore",
                "menu-file",
                "menu-view",
                "version-not-in-history",
            ] {
                assert!(
                    entries.iter().any(|(k, _)| k == key),
                    "{lang} is missing the port-added key {key}"
                );
            }
        }
    }

    /// Every literal key the app's sources hand the lookup macro exists in
    /// en (the parity test above carries it to it/de/fr): keys resolve at
    /// run time, so a typo would render the raw id.
    #[test]
    fn every_macro_key_in_the_sources_exists_in_the_catalog() {
        fn rust_files(dir: &std::path::Path, out: &mut Vec<PathBuf>) {
            for entry in std::fs::read_dir(dir).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    rust_files(&path, out);
                } else if path.extension().is_some_and(|ext| ext == "rs") {
                    out.push(path);
                }
            }
        }
        let en: BTreeSet<String> = parse_ftl(&i18n_dir().join("en/main.ftl").to_string_lossy())
            .into_iter()
            .map(|(key, _)| key)
            .collect();
        let mut files = Vec::new();
        rust_files(
            &PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src"),
            &mut files,
        );
        let opener = concat!("fl", "!(");
        let mut seen = 0;
        let mut missing = Vec::new();
        for file in files {
            let text = std::fs::read_to_string(&file).unwrap();
            for (at, _) in text.match_indices(opener) {
                let Some(rest) = text[at + opener.len()..].trim_start().strip_prefix('"') else {
                    continue;
                };
                let key = &rest[..rest.find('"').unwrap()];
                seen += 1;
                if !en.contains(key) {
                    missing.push(format!("{}: {key}", file.display()));
                }
            }
        }
        assert!(seen > 200, "the scan found the call sites: {seen}");
        assert!(missing.is_empty(), "keys missing from en: {missing:#?}");
    }

    /// The selection override: a valid persisted tag selects exactly that
    /// language; None (or garbage a hand-edited settings.json might carry)
    /// falls back to the desktop request without panicking.
    #[test]
    fn override_selects_or_falls_back_to_the_desktop_request() {
        let _lang = pin_en();
        localize_with_override(Some("it"));
        assert_eq!(fl!("pronto"), "Pronto");
        assert_eq!(
            fl!("sta-lavorando", agent = "Claude Code"),
            "Claude Code sta lavorando…"
        );
        // an unparseable tag must not panic — it falls back to the
        // desktop-request language
        localize_with_override(Some("not a langid"));
        localize_with_override(None);
        // restore EN no matter what the fallbacks above did: the loader is
        // GLOBAL and this test's overrides leak into unpinned catalog-text
        // tests in other modules under --test-threads=1 (a deterministic
        // failure otherwise — "Pagina 3" != "Page 3")
        select("en");
    }
}
